custom_css:
/* Chiaro: superfici piene, meno rumore */
.drawer-content {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
}
.drag-grabber { display: none !important; }
.mes .mes_buttons { opacity: 0.25; transition: opacity 0.15s ease; }
.mes:hover .mes_buttons, .mes .mes_buttons:focus-within { opacity: 1; }
.mes_timer { display: none !important; }
#send_but { color: var(--SmartThemeQuoteColor); }
#mes_stop { color: #c04b4b; }
#send_textarea:focus { border-color: rgba(255, 255, 255, 0.25) !important; outline: none; }
#top-settings-holder { border-bottom: 1px solid rgba(255, 255, 255, 0.06); }
.name_text { font-weight: 600; }
::selection { background: rgba(240, 160, 75, 0.35); }
*::-webkit-scrollbar { width: 8px; height: 8px; }
*::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.15); border-radius: 4px; }
*::-webkit-scrollbar-track { background: transparent; }
* { scrollbar-width: thin; scrollbar-color: rgba(255, 255, 255, 0.15) transparent; }
